from collections import deque
shown = [('a','b'),('b','c'),('c','d'),('a','f'),('f','c'),('c','h'),('e','f'),('f','g'),('g','h')]
def dist(E, s, t):
    adj = {}
    for u, v in E:
        adj.setdefault(u, set()).add(v); adj.setdefault(v, set()).add(u)
    D = {s: 0}; q = deque([s])
    while q:
        u = q.popleft()
        for w in adj.get(u, ()):
            if w not in D: D[w] = D[u] + 1; q.append(w)
    return D.get(t)
# given shortest paths, each of length 3
given = [('a','d'), ('e','h'), ('a','h')]
print('shown graph distances:', [(s, t, dist(shown, s, t)) for s, t in given])
for lab, e in zip('ABCD', [('b','d'), ('b','g'), ('b','h'), ('e','g')]):
    d = [dist(shown + [e], s, t) for s, t in given]
    ok = all(x == 3 for x in d)
    print(lab, e, 'distances with edge added:', d,
          '-> consistent (could be an edge)' if ok else '-> contradicts a given shortest path (NOT an edge)')
